begin;
set local lock_timeout='5s';
lock table questions,question_keys,revision_items in share row exclusive mode;
create temporary table est_review_batch on commit drop as
select * from jsonb_to_recordset('[{"id":"00b95126-e20b-5874-9cdf-5e521e1f0f04","status":"mathematically_verified","solution":"Numerator = (4−6+2)m√(3a)=0; denominator positive; C.","expected_key":"C","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"29c7622bf62e1780d69ffae124319dfa","key_digest":"9d49f1f88a0360a977cc057cda454b53","fingerprint":"4e3dc2fe258afd4548711ee288b344f5","old_stem":"Which of the following is equivalent to (4m√(3a) − 2√(27am²) + m√(12a)) / √(243a³) for all positive values of a and m?"},{"id":"016c3282-6338-5f41-adb8-bf518964f869","status":"mathematically_verified","solution":"At 2014 x=3; prediction2603.3; source blue observed2550; residual magnitude53.3; C.","expected_key":"C","source_image_checked":true,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"image":"https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-067-1.png"},"q_digest":"0a4e30f4a2831063dc46e86f1c975b9c","key_digest":"276f490057350a998418d2fdefff1662","fingerprint":"ed58162eb6fa5e07e509d9389c9c5774","old_stem":"The graph shows observed values and fitted curves. Year 2011 is x = 0. Village B’s fitted line is y = 194.3x + 2,020.4. What is the closest difference between the actual number of boys in village B and the number which can be predicted from the line of best fit in 2014?"},{"id":"02356ac9-1bbe-5edb-bfdb-e944a15afb12","status":"mathematically_verified","solution":"Substitute A:-1,B:4,C:5,D:14; only14>5; D.","expected_key":"D","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"843ae2e544ffd0f612aa22148ebdc5be","key_digest":"ee583dc051383a946d9f71d0ce18c3e3","fingerprint":"a38f55746f58e7ac55ca263bff9db6c2","old_stem":"Which of the following ordered pairs (x, y) satisfies the inequality 2x + 3y > 5?"},{"id":"023c95b9-3fb8-52f4-8240-fc8aef8da2bd","status":"repair_and_verified","solution":"dx=2,dy=−1; distance²=5; C; original image read.","expected_key":"C","source_image_checked":true,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"stem":"The distance between A(1, −1) and B(3, −2) is √k, where k is a real number. What is the value of k?","choices":[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"5"},{"key":"D","text":"7"}],"image":"https://math.portal.ghoneem.com/exams/est-march-2026/q48.png"},"q_digest":"86a84eebf09b4396bc525009a4d5b972","key_digest":"e2dea9844f987b269b5e6d7eda06a3b2","fingerprint":"df332716428aa3b15bf00253b3068a06","old_stem":"EST I Math — March 2026 · Question 48. Select the answer from the original question below."},{"id":"034f4fb8-74f6-5e61-974d-78bb2b5b0da5","status":"mathematically_verified","solution":"11/(3+11)*350=275; D.","expected_key":"D","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"84c132e3070c600a88fa95902ed3036b","key_digest":"72e7109ef440a9048317d51a97a74156","fingerprint":"6c9741d279d67fc8f0624ca8019e9c8d","old_stem":"Maria has 350 pop and rock songs in the ratio 3:11. How many are rock songs?"},{"id":"03601fa8-c9c9-5638-8897-8bbb86669445","status":"repair_and_verified","solution":"15+0.3x; only A has fixed15 and rate0.3.","expected_key":"A","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"stem":"Amira registered in an online magazine for a monthly fee of USD 15. However, to read premium articles, she has to pay an extra charge of USD 0.3 per article. Which of the following represents the total amount Amira is going to pay per month if she reads x premium articles?","choices":[{"key":"A","text":"0.3x + 15"},{"key":"B","text":"0.3x + 15 × 30"},{"key":"C","text":"15x + 0.3"},{"key":"D","text":"15 × 30x + 0.3"}],"explanation":"A fixed charge of USD 15 plus USD 0.30 per unit x gives C = 15 + 0.30x."},"q_digest":"c68b0cb513a5fd80e8b53fa18be2337b","key_digest":"5dcc9dde53e795565366ad2031d52f9a","fingerprint":"3f7a9942a588814eac8e8927a20aff6d","old_stem":"Amira registered in an online magazine for a monthly fee of $15. However, to read premium articles, she has to pay an extra charge of $0.3 per article. Which of the following represents the total amount Amira is going to pay per month if she reads x premium articles?"},{"id":"0398f66f-3326-5d60-8a9d-318dd3047685","status":"repair_and_verified","solution":"12>10 uses10% salary bonus:1300*1.1=1430; B.","expected_key":"B","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"stem":"Rima is a saleswoman in a TV store. Her salary is USD 1,300 per month. She gets an additional USD 10 for every TV she sells if the quantity sold is less than or equal to 10 TVs per month. If she sells more than 10 TVs in one month, she will get an extra bonus of 10% of her initial salary. Last November, she sold 12 TVs. What was her salary at the end of the month?","choices":[{"key":"A","text":"1,420"},{"key":"B","text":"1,430"},{"key":"C","text":"1,450"},{"key":"D","text":"1,550"}],"explanation":"For more than 10 TVs the stated rule gives a 10% bonus on the USD 1,300 base salary: 1,300 × 1.10 = USD 1,430."},"q_digest":"57c3a590457b4c151304a8a08bea3ec6","key_digest":"10646f3e3f1ff1b7d8b292ab9b8f0e03","fingerprint":"03169c40569315896077ec50125c9fbb","old_stem":"Rima is a saleswoman in a TV store. Her salary is $1,300 per month. She gets an additional $10 for every TV she sells if the quantity sold is less than or equal to 10 TVs per month. If she sells more than 10 TVs in one month, she will get an extra bonus of 10% of her initial salary. Last November, she sold 12 TVs. What was her salary at the end of the month?"},{"id":"04b9f396-e79e-5cb8-b2ce-a5f07ad754e4","status":"mathematically_verified","solution":"x²−3x+2=(x−1)(x−2); product2; D.","expected_key":"D","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"7fb8a9568d6e50ab2951db60e253ae4c","key_digest":"3256ecc7de0a15ba48d23a3fb964bfca","fingerprint":"19861b7c7bb75f66b42adb4116bd5c2b","old_stem":"What is the product of the solutions of the equation x² − 3x = −2?"},{"id":"04be0054-500f-5350-b592-51e254d5e781","status":"repair_and_verified","solution":"2r+5d=6,4r+2d=4 => d=1,r=0.5;2r+2d=3;D.","expected_key":"D","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"stem":"Amina went to the flower shop and bought 2 roses and 5 daisies for USD 6. From the same shop, Lara bought 4 roses and 2 daisies for USD 4. How much should Ahmad expect to pay for 2 roses and 2 daisies?","choices":[{"key":"A","text":"USD 1.0"},{"key":"B","text":"USD 1.5"},{"key":"C","text":"USD 2.0"},{"key":"D","text":"USD 3.0"}],"explanation":"Solving 2r + 5d = 6 and 4r + 2d = 4 gives d = 1 and r = 1/2. Therefore 2r + 2d = USD 3."},"q_digest":"7c0e5ba36ab1484a7907281f7452d785","key_digest":"6663f7f51a64169ffb048efbe3fc7f8e","fingerprint":"b0b670d1f710336f7e51ab4187fbcab1","old_stem":"Amina went to the flower shop and bought 2 roses and 5 daisies for $6. From the same shop, Lara bought 4 roses and 2 daisies for $4. How much should Ahmad expect to pay for 2 roses and 2 daisies?"},{"id":"0548f714-8291-5f58-8376-5cb635981f47","status":"mathematically_verified","solution":"9 geometry+6 algebra+6 trig=21/30=70%; C.","expected_key":"C","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"4ec966d801ef08bcfee6f02c5f3826f3","key_digest":"a871fb152c5376ca200eabd73316205d","fingerprint":"26c685b951c1078064ee2f7e2056debd","old_stem":"On a math test of 30 questions, Mona got 75% of the 12 geometry questions correct, 60% of the 10 algebra questions correct, and 25% of the 8 trigonometry questions wrong. What percentage of all the questions did Mona get correct?"},{"id":"0577ad03-033b-5ec9-a541-55a7cdf4d93c","status":"mathematically_verified","solution":"Force ratio=(r/3r)²=1/9; D.","expected_key":"D","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"649e63200ec7929ac96e372c7962ed9a","key_digest":"79505411096368e967fd0b1c5f4f48e1","fingerprint":"0c5d75b3242fa07484b8d663b1350072","old_stem":"For fixed charges and permittivity, F = q₁q₂/(4πε₀r²). If the separation is increased from r to 3r, what is the new force F₁ in terms of F?"},{"id":"058c6b55-fed1-5016-884a-9a523163c4d9","status":"mathematically_verified","solution":"Source box endpoints Q1=6,Q3=20;IQR14; B.","expected_key":"B","source_image_checked":true,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"image":"https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-022-1.png"},"q_digest":"abe3bf15c2728aa587d86e44182318ff","key_digest":"b2bb4b7f8350dd92a1e412f11c28dd0a","fingerprint":"d0f70d8833e7ed418b91a34b34b36283","old_stem":"The box plot represents the ages of actors in a TV series. What is the interquartile range of the data collected?"},{"id":"059baedd-7054-522f-addb-6262697310dc","status":"repair_and_verified","solution":"120*0.9=108 good,12 defective;108*40+12*20=4560; C.","expected_key":"C","source_image_checked":true,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"stem":"A bookstore has 120 books. Ten percent are defective. Each non-defective book is sold for 40 dollars, and each defective book is sold for half that price. What is the total revenue from selling all the books?","choices":[{"key":"A","text":"4200"},{"key":"B","text":"4320"},{"key":"C","text":"4560"},{"key":"D","text":"4600"}]},"q_digest":"615226cc6db54efb4411f3552ebde36b","key_digest":"a39609333f3923e86457c93ee1bf1d77","fingerprint":"88b941fb4bd51e45aad0b5f19292054d","old_stem":"PSD 222 — Answer the original question below."},{"id":"06425acd-66b1-52cc-ae20-8f25158f1735","status":"mathematically_verified","solution":"twice number minus2=3times number =>2x−2=3x; C.","expected_key":"C","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"ea3625f6c5963c0d03ba6d4bfe671275","key_digest":"e1a8b0c377e29071097e0a560c55dc8e","fingerprint":"96f5947b3b00f8a31696f3ef0e8fc3db","old_stem":"The difference between twice a number and two is three times this number. Which of the following represents the equation that the number verifies?"},{"id":"06d16da3-f0d7-55b9-80f6-00dcd03bc23a","status":"repair_and_verified","solution":"Graph intersects y=1.5 at x0, strictly increasing implies unique; A.","expected_key":"A","source_image_checked":true,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"stem":"The graph shows an increasing function f. What is the solution of f(x) − 1.5 = 0?","choices":[{"key":"A","text":"0"},{"key":"B","text":"1.5"},{"key":"C","text":"3"},{"key":"D","text":"4.5"}],"explanation":"Solving f(x) − 1.5 = 0 means finding where f(x) = 1.5. The graph crosses the y-axis at 1.5 and is increasing, so the only solution is x = 0."},"q_digest":"1a1089011b70409030be781a42d965f6","key_digest":"8e817982e1ed137f57a63fe69eb61937","fingerprint":"e10b5f4429beb77e36572f035b6a41b4","old_stem":"PAM 019 — Answer the original question below."},{"id":"07153eab-b798-435f-a999-7c224e73d396","status":"mathematically_verified","solution":"1/(x+2)+1; asymptotes x−2,y1; original options D matches; D.","expected_key":"D","source_image_checked":true,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"9ee2f83a0eab397993b069d55b2c8fa5","key_digest":"c6f0926d7f271d66afa799855957cc66","fingerprint":"f16a216d388776fc96e662049dce89c7","old_stem":"Which of the following represents the graph of $f(x)=\\dfrac{2}{2x+4}+1$?"},{"id":"0750b96d-174c-5957-8049-7b8f33312460","status":"mathematically_verified","solution":"Expansion is 6x²−5x−6; the coefficient of x is −5, key B.","expected_key":"B","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"240feb00a5a4a3374965d217365c8fc4","key_digest":"2f430207d25512fe5c50755a7a086402","fingerprint":"b05be7e3720a6c9fe3d6cd4696ad63b8","old_stem":"What is the resulting coefficient of x when −2x + 3 is multiplied by −3x − 2?"},{"id":"07779610-2dd2-5d50-b2e7-7f8b4b30a7a7","status":"repair_and_verified","solution":"September has30days−4=26 working days; fiancee26*11*10.7=3060.2;Adam(11000−3060.2)/(26*15)=20.35846, closest20.4; C.","expected_key":"C","source_image_checked":true,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"stem":"Questions 20 to 22 refer to a graph of Adam and his fiancée''s combined monthly salaries (in thousands of dollars) during 2019: Jan 2, Feb 3, Mar 2, Apr 8, May 6, Jun 4, Jul 2, Aug 1, Sep 11, Oct 9, Nov 3, Dec 6. — During September, Adam worked 15 hours per day, while his fiancée worked 11 hours per day. Knowing that each one of them took 4 days off that month, and his fiancée was getting paid USD 10.7 per hour, how much was Adam approximately getting paid per hour?","choices":[{"key":"A","text":"USD 16.6"},{"key":"B","text":"USD 17.8"},{"key":"C","text":"USD 20.4"},{"key":"D","text":"USD 36.1"}],"explanation":"Each worked 26 days. His fiancée earned 26 × 11 × 10.7 = USD 3,060.20. Adam''s hourly rate was (11,000 − 3,060.20)/(26 × 15) ≈ USD 20.36, closest to USD 20.4.","image":"https://math.portal.ghoneem.com/exams/est-banks-2026/figures/dap-013-1.png"},"q_digest":"44c14f63917c3657d3b0ec7e50c8f10a","key_digest":"c429cc38d9989be85a04fc2b07e35f6e","fingerprint":"f99484bc9a62a09333e6e74489270fc9","old_stem":"Questions 20 to 22 refer to a graph of Adam and his fiancée''s combined monthly salaries (in thousands of dollars) during 2019: Jan 2, Feb 3, Mar 2, Apr 8, May 6, Jun 4, Jul 2, Aug 1, Sep 11, Oct 9, Nov 3, Dec 6. — During September, Adam worked 15 hours per day, while his fiancée worked 11 hours per day. Knowing that each one of them took 4 days off that month, and his fiancée was getting paid $10.7 per hour, how much was Adam approximately getting paid per hour?"},{"id":"0925bb94-9e4d-50c3-b5fb-c8ade4ff1386","status":"repair_and_verified","solution":"CityA weighted171/80=2.1375 median/mode2;CityB205/80=2.5625 median/mode3; all different D.","expected_key":"D","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"explanation":"City A: mean = (25 + 62 + 42 + 32 + 10)/80 = 171/80 = 2.1375, median = 2, mode = 2. City B: mean = (20 + 38 + 69 + 48 + 30)/80 = 205/80 = 2.5625, median = 3, mode = 3. None of the three measures is the same."},"q_digest":"4266b9d0044fcd0d79c0c412d7ad8a1e","key_digest":"43808074431fb3e0fdd1e6a75b80ef2a","fingerprint":"9c95254eaae6a6c869a87a9efac89c29","old_stem":"A survey covers 80 families in each city. Number of cars: City A frequency, City B frequency — 1: 25, 20; 2: 31, 19; 3: 14, 23; 4: 8, 12; 5: 2, 6. Which measure of center is unchanged in both cities?"},{"id":"0b3427bf-8344-55d2-8ab9-32cf406306ed","status":"repair_and_verified","solution":"Combined rate2*600=1200m/h;300/1200h=15minutes; A; source crop checked.","expected_key":"A","source_image_checked":true,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"stem":"A machine paves 600 meters of road in 1 hour at a steady rate. How much time would two identical machines take to pave 300 meters?","choices":[{"key":"A","text":"15 minutes"},{"key":"B","text":"2 hours"},{"key":"C","text":"1 hour"},{"key":"D","text":"30 minutes"}]},"q_digest":"121b794fe898a401d6c128e5fd70c7da","key_digest":"6a4aa9b19510c66a55614b80ad413051","fingerprint":"21f979934e0ad193953ebd8a8aac48be","old_stem":"PSD 077 — Answer the original question below."},{"id":"0cbfc70e-50ea-5fdc-9a2d-f8119fc9b5cb","status":"mathematically_verified","solution":"Solid boundary through(0,−3),(6,0); shading above means y≥0.5x−3, equivalent to −y≤−0.5x+3; B.","expected_key":"B","source_image_checked":true,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"image":"https://math.portal.ghoneem.com/exams/est-banks-2026/figures/fa-012-1.png"},"q_digest":"230f965b32fdfea2bc3e7661a5237281","key_digest":"3034ba4f0f561e3a943ec37e52416321","fingerprint":"490dea3ce043e01e036099a36fe849e7","old_stem":"Which of the inequalities below represents the shaded region in the figure?"},{"id":"0d1610df-2ffc-5a6e-a793-671b0513f37f","status":"repair_and_verified","solution":"2p+n=2.75,3p+2n=4.75 =>p0.75,n1.25; C.","expected_key":"C","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"stem":"Amar and Raya went together to the bookstore. Amar bought 2 pens and 1 notebook and paid USD 2.75. Raya bought 3 pens and 2 notebooks and paid USD 4.75. What is the price of the notebook in this bookstore?","choices":[{"key":"A","text":"USD 0.75"},{"key":"B","text":"USD 1.0"},{"key":"C","text":"USD 1.25"},{"key":"D","text":"USD 1.50"}],"explanation":"Solving the two purchase equations gives a pen price of USD 0.75 and a notebook price of USD 1.25; substitution reproduces both totals."},"q_digest":"97b5e44510966370a67db2d69efb3b57","key_digest":"2f0a26866a7b86352c68c1131a837c1c","fingerprint":"ccbd1ccb8f5867c484faa2ec44fb7c29","old_stem":"Amar and Raya went together to the bookstore. Amar bought 2 pens and 1 notebook and paid $2.75. Raya bought 3 pens and 2 notebooks and paid $4.75. What is the price of the notebook in this bookstore?"},{"id":"0eb213c2-a947-58c2-b9c1-b7c7c2bebe77","status":"repair_and_verified","solution":"right+45 yields45−45−90;hypotenuse4.4sqrt2=6.2225 =>6; D.","expected_key":"D","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{"explanation":"Since triangle REF is right at R and angle REF = 45°, its third angle is also 45°. The legs are equal and EF is the hypotenuse. Thus EF = 4.4√2 ≈ 6.2225 cm, which rounds to 6 cm."},"q_digest":"6d59071dcd547a92a4eab78a3391797b","key_digest":"d84aafddc6031cc0661fb821e4c5f7a6","fingerprint":"adbd54fba979ef227ad400b28c5e1d59","old_stem":"REF is a right triangle at R with m∠REF = 45°. If RE = 4.4 cm, what is the length of EF to the nearest cm?"},{"id":"0f40726b-1397-5461-b7e0-7980f4b40bd9","status":"mathematically_verified","solution":"Vertex abscissa−(−18)/(2*3)=3; B.","expected_key":"B","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"176d69dd9f9a37f4eea919a8e24fefb4","key_digest":"41ea11376f9c19cb162c46aa0d93013a","fingerprint":"6eb3d0911f151dfaac91f81b7750b082","old_stem":"What is the abscissa of the vertex of the function f(x) = 3x² − 18x + 4?"},{"id":"0f4f82f5-f03a-5549-acf2-0dd61fa9faf5","status":"mathematically_verified","solution":"At m=0,g12 full tank;B.","expected_key":"B","source_image_checked":false,"scope":"Current complete stem, choices and worked solution; source images checked where needed","repair":{},"q_digest":"db5cbcc98e3d49b0e6817c5d26450866","key_digest":"d9681ff9bcd91c5239ee4c5a9431c179","fingerprint":"d2cda8a5c94f76de727aa6de3cb91d7d","old_stem":"Questions 4 and 5 refer to the equation g = 12 − m/20. Ibrahim fills up the gas tank of his car before going on a trip. The equation models the number of gallons of gas g remaining in Ibrahim''s car after he has driven m kilometers. — How many gallons of gas can Ibrahim''s tank hold?"}]'::jsonb)
as t(id uuid,status text,solution text,expected_key text,source_image_checked boolean,scope text,repair jsonb,q_digest text,key_digest text,fingerprint text,old_stem text);
do $$ begin
if exists(select 1 from audit_log where action='questions.est_remaining_batch01.20260930') then raise exception 'Batch already applied'; end if;
if (select count(*) from est_review_batch t join questions q on q.id=t.id join question_keys k on k.question_id=q.id where q.track_id='est' and md5(to_jsonb(q)::text)=t.q_digest and md5(to_jsonb(k)::text)=t.key_digest and k.correct#>>'{}'=t.expected_key and nullif(q.assets->>'release_hold_reason','') is null)<>25 then raise exception 'Reviewed question version changed'; end if;
end $$;
create temporary table est_review_revision_before on commit drop as
select r.question_id,r.active,r.fingerprint=t.fingerprint was_ready
from revision_items r join est_review_batch t on t.id=r.question_id;
insert into audit_log(action,target_type,target_id,meta)
select 'questions.est_remaining_batch01.20260930','question',q.id::text,
jsonb_build_object('previous_stem',q.stem,'previous_choices',q.choices,'previous_assets',q.assets,'previous_explanation',k.explanation,'solution',t.solution,'scope',t.scope,'source_image_checked',t.source_image_checked,'status',t.status)
from est_review_batch t join questions q on q.id=t.id join question_keys k on k.question_id=q.id;
update questions q set
stem=coalesce(t.repair->>'stem',q.stem),
choices=coalesce(t.repair->'choices',q.choices),
assets=q.assets||jsonb_build_object('answer_review','2026-09-30-independent-current-stem-review','mathematical_review_scope',t.scope)||
case when t.repair ? 'image' then jsonb_build_object('image',t.repair->>'image') else '{}'::jsonb end
from est_review_batch t where q.id=t.id;
update question_keys k set explanation=t.repair->>'explanation'
from est_review_batch t where k.question_id=t.id and t.repair ? 'explanation';
update revision_items r set fingerprint=revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation)
from questions q join question_keys k on k.question_id=q.id join est_review_revision_before b on b.question_id=q.id
where r.question_id=q.id and b.was_ready;
do $$ begin
if exists(select 1 from est_review_revision_before b join revision_items r using(question_id) where r.active is distinct from b.active) then raise exception 'Release status changed'; end if;
if (select count(*) from audit_log where action='questions.est_remaining_batch01.20260930')<>25 then raise exception 'Audit incomplete'; end if;
end $$;
commit;
